mapper.select:
SELECT u.id, u.user_id, m.title, m.content, m.attachment_urls AS attachmentUrls, m.type, u.status, u.read_time, m.sender_id, m.sender_name, u.create_time, u.update_time FROM sys_notification_user u LEFT JOIN sys_notification_msg m ON u.notification_id = m.id
AND m.is_deleted = 0
AND u.user_id = #{query.userId}
AND m.type = #{query.type}
AND u.status = #{query.status}
AND m.title LIKE CONCAT('%', #{query.title}, '%')
AND u.create_time >= #{query.startTime}
AND u.create_time <= #{query.endTime}
ORDER BY u.create_time DESC
